module find_polynomial (\n    input clk,\n    input rst_n,\n    input start,\n    input [59:0] p_in,\n    input [11:0] k_in,\n    output reg [11:0] coeff,\n    output reg valid,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    \n    reg [1:0] state;\n    reg signed [59:0] p_reg;\n    reg signed [11:0] k_reg;\n\n    // Combinational quotient and remainder\n    wire signed [59:0] quotient;\n    wire signed [11:0] remainder;\n\n    assign quotient = p_reg / k_reg;\n    assign remainder = p_reg % k_reg;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            p_reg <= 60'sd0;\n            k_reg <= 12'sd0;\n            coeff <= 12'd0;\n            valid <= 1'b0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    valid <= 1'b0;\n                    if (start) begin\n                        p_reg <= $signed(p_in);\n                        k_reg <= $signed({1'b0, k_in});\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (p_reg != 60'sd0) begin\n                        if (remainder < 12'sd0) begin\n                            coeff <= $unsigned(remainder + k_reg);\n                            p_reg <= - (quotient + 60'sd1);\n                        end else begin\n                            coeff <= $unsigned(remainder);\n                            p_reg <= - quotient;\n                        end\n                        valid <= 1'b1;\n                    end else begin\n                        done <= 1'b1;\n                        valid <= 1'b0;\n                        state <= IDLE;\n                    end\n                end\n                \n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule